// ── CENTAURIAN SHIP SPRITES ──────────────────────────────────────────────────
const CENTAURIAN_B64 = {
  fighter: "",
  cruiser: "",
  frigate: "",
  capital: "",
};
const centaurianImgs = {};
Object.entries(CENTAURIAN_B64).forEach(([k,v])=>{
  centaurianImgs[k] = new Image();
  centaurianImgs[k].src = "data:image/png;base64," + v;
});

